- B sẽn yaa yɩngã sã n wa, b pa tõe n yɩɩb ye, pa tõe n tɩɩms ye. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- La y pa tũ a Toolmã sorã ye, yaa a yaa y ka-biis vẽenega. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- La nebã sʋka, yaa neb nins sẽn pa wʋm bũmb ye. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- Wẽnnaam kõta ned ning a sẽn datã, la Wẽnnaam yaa Kʋɩf Naabã. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- N yɩɩ fãa na n paam a tʋʋmã ar-laafã, la b pa maan b wẽng ye. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- La y pa kʋ n yɩɩmd Wẽnnaam sẽn kɩɩsã, rẽ yĩnga. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- A sã n tɩ yã bũmb, a yeela: Yɩ. (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- Kẽ-y Gɛhannam noorã pʋgẽ, y na n yɩɩ pʋw-la; la yaa yɩɩg bɛɛga wẽng sẽn yaa mamd-rãmbã! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- Fo pa yã b sẽn kõ Gʋlsʋm pʋɩɩgã? (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- B tara arzãan-rãmb, dũri sẽn yiid b tẽnga, b na n yɩɩ pʋw-la. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- E m nin-buiidã! Tʋm-y y sẽn yaa, mam me tʋmdame, la y na n bãng. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- Ned ning sẽn kɩɩs Wẽnnaam la A Tʋmtã, a tar Gɛhannam bugum, a na n yɩɩ pʋw-la. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- Tõnd kɩt tɩ b sũyã pʋgẽ, b pa tõe n bãng ye, la b tʋbã pʋgẽ sẽn yɩɩ kɩbkɩbre. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- Tẽng sẽn yaa fãa, tõnd sẽn tʋm mensaag, b mensã yeelame: Tõnd. (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- B yeelame: Sɩng-y tõnd Soabã t'a vẽneg tõnd bũmb ningã. (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- B na n yeele: Wẽnnaam. Yeele: Pʋʋs yaa Wẽnnaam yĩnga! La b wʋsg. (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْdُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- A nin-buiidã leok yaa: Yees-y bãmba. (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- Dũri yiid b tẽnga, b na n yɩɩ pʋw-la; rẽ yaa paoong sẽn yaa gãnda. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- B rãmbã yaa ne soolem sẽn yi a Soabã nengẽ, la b rãmbã yaa b sẽn paam. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- Ned ning naong sẽn yaa yɛɛsa na n wa a zugu, la naong sẽn ka baoodẽ. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- Gũ-y tẽngã zug n ges nand tɩɩr sẽn yaa sẽn kɩɩs-a. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- B pa na n yel yam n paam ye, bũmb sẽn yaa b nusã sẽn tʋmã, la Wẽnnaam mi nin-wẽns rãmbã. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- A yaa n bãng bũmb sẽn yaa bõn-dã, la a yaa bãngrã. (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- Sɩd-sɩda, Wẽnnaam yaa m Soabã la y Soabã, bʋd tũm-y ne-a; rẽ yaa sor sẽn yaa tɩrgã. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- A yaa Kʋɩf Naabã, la b wʋsg pa pʋʋs ye. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- Tõnd pa naan saasã la tẽngã la bũmb nins sẽn be b sʋka, rẽ yĩng ye. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- Bas-b b tɩ yɩ sõngrã pʋgẽ la b tɩ pɛɛm, hal tɩ b tɩ tõog b daar sẽn pʋlemã. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- B sã n tõog sɩd-rãmbã, b yeela: Tõnd kõ sɩd, la b sã n yɩɩ yembr. (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- B yɩɩda Taurat la Ingil la bũmb sẽn sɩdg bãmb nengẽ, a Soabã. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- A mi bũmb sẽn be b taoorã la sẽn be b poorẽ, la b pa tõe n mi. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- La a yaa sẽn naan saasã la tẽngã daar a yõob pʋgẽ. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- Sɩd-sɩda, bũmb ningã pʋgẽ, yaa tagl y yĩnga, sã n yaa y rãmbã. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- Bõe n kɩɩs nebã sɩd paama, sõng sẽn wa bãmb nengẽ? (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- B kɩt tɩ Wẽnnaam tara mako, tɩ b bõng a sorã. Yeele: Pʋʋm-y y sũur. (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- B yõoogame, b sẽn paam mensaag a yembr b sʋka, la kɩɩsdb yeelame: Rũndã. (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- Sɩd-sɩda, fo Soabã yaa n bãng bũmb sẽn yaa bõn-dã. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- Wala ned sẽn kõ a arzɛkã nebã yĩnga, la a pa kõ Wẽnnaam sɩd ye. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- Kõ-y bũmb sẽn yaa Tõnd kõ-yã, sẽn pa n wa. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- A kɩt tɩ bũmb sẽn be saasã la tẽngã pʋgẽ yaa y yĩnga. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- La tõnd, sɩd-sɩda, d be zɛɛr pʋgẽ, bũmb ning y sẽn bool tõndã. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- Sɩd-sɩda, fo Soabã yɩɩda arzɛk ned ning a sẽn datã, la a kɩt tɩ ka wʋs. Sɩd-sɩda, a yaa. (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- Saasã la tẽngã la bũmb nins sẽn be b sʋkã Soabã, sã n yaa y rãmbã. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- Tõnd kõ sɩd ne Wẽnnaam, la bũmb sẽn sɩdg tõnd nengẽ, la bũmb sẽn sɩdg. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- La nin-wẽns rãmbã, yɩɩgã wa n yõk-ba, b yɩɩ b zagsã pʋgẽ. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- Y pa tar zʋʋr bũmb sẽn yaa b sẽn maan b mens yĩng ye. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- Fo Soabã yaa n bãng bũmb sẽn yaa bõn-dã, la a yaa. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- Ne roogo (sɩd-sõngr) a Sagendẽ, ned ning a sẽn datã, a dãmbã sʋka. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- La tõnd kõ Issa, Maryam biigã, tagla sẽn ka vẽeneg, la tõnd sõng-a ne Roogo sẽn yaa sõngrã. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- T'a fʋt b taabã Yikrã raarã, bũmb sẽn yɩɩ maan waoodã. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- Tõnd kɩt tɩ a zugu yɩɩ a tẽnga, la tõnd sɩdga kug-kãens sẽn yaa zĩm sẽn yaa kɩbg pʋgẽ. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- Yɩɩ yembr ne bãmb, fo mens-y bãmb, wala fo pa mens, b pa kõ sɩd ye. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- Rẽ yĩnga nebã, bʋd y yɩ yam n bao kũum, sã n yaa y rãmbã. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- Wẽnnaam, y tara soab a taab ye. Yaa b yɛɛsdã? (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- Sã n wa yã bũmb sẽn yaa d sẽn pʋlem-bã, wala d na n ki-fo, b lebgr yaa d nengẽ. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- B yeelame: Yaa b tõnd sã n ki, la d yɩɩ gũbr la kũuda, yaa b d na n yik? (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- Sɩd-sɩda, kʋɩfga be Wẽnnaam nusã, a kõta ned ning a sẽn datã, la Wẽnnaam. (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- La y na n lebg n dɩk bũmb sẽn ka vẽeneg la sẽn vẽenegã, t'a vẽneg y sẽn da maanã. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- Y sɩd-rãmbã, bʋd y teeg Wẽnnaam kʋɩfg a sẽn maan yãmbã, wakat ningã. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- La tõnd pa tʋm raood foom, rẽ yĩng ye, la rao-rãmb, tõnd sẽn tʋm sɩd-sõngr ne-ba. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- A na n sak a tʋʋm-beedã la a kẽes-a la arzãanã pʋgẽ, dũri sẽn yiid a tẽnga. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- Ned sẽn yaa kʋɩrga, wala ned sẽn be sorã, t'a pʋd daar a taabã. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- B pa tũd, rẽ yĩng ye, la b pa tũd, rẽ yĩng ye. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- Ned sẽn dat Wẽnnaam la daar sẽn yaa kõ-rãmbã, yaa tʋʋmd sẽn yaa sõma. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- La tõnd pa naan saasã la tẽngã la bũmb nins sẽn be b sʋka, rẽ yĩng ye. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- Dɩk f nuu ne f togã pʋgẽ, a na n yii, a yɩɩ yõk-tɩ, pa tar bõne. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- A yɩɩda ned ning a sẽn datã ne a yel-nongrã, la Wẽnnaam yaa Kʋɩf Naabã. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- Fo pa mi tɩ Wẽnnaam soaba saasã la tẽngã naabã? (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- La bũmb sõma fãa y sẽn tʋm y mens yĩnga, y na n yã a Wẽnnaam nengẽ. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- La y sẽn yi bũmb ning fãa, yãk-y y ningã ne Masyɩd sẽn yaa sõngrã. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- B sẽn da be y taoorã, la fo pa na n yã Wẽnnaam sorã sakri ye. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- B sẽn tara bũmb nins sẽn be saasã la tẽngã pʋgẽ. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- La pagã pa dɩk pʋg-la, la pa dɩk biig ye, rẽ yĩng ye. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- A kɩt tɩ yʋngã, wĩndgã la kiuugã yaa y yĩnga; b fãa yɩɩda wakat sẽn yaa bãngrã. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- Dũri yiid b tẽnga, b na n yɩɩ pʋw-la, la rẽ yaa ar-laafã. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- A yeelame: Ayo, la y sũyã yaa sẽn maan y bũmb ninsã, tɩ yɩɩ sõma. (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- Bũmb nins sẽn be saasã la tẽngã pʋgẽ, la sɩd-sɩda, Wẽnnaam. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- La b sẽn paam tʋmt a yembr, b maana a kɩɩsgã. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- B yeelame: Mousa! Fo na n loe, wala tõnd na n loe? (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- A yaa sẽn kʋ yãmb, la y sʋka, yaa ned ning b sẽn lebsd a yɩɩgã, tɩ. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- B tara arzãan-rãmb ne b Soabã, dũri sẽn yiid b tẽnga, b na n yɩɩ pʋw-la. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- La tõnd kɩt tɩ b sũyã pʋgẽ, b pa tõe n bãng ye, la b tʋbã pʋgẽ kɩbkɩbre. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- Sɩd-sɩda, Wẽnnaam pʋlem yaa sɩd, la b wʋsg pa mi ye. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- Rẽ yĩng tɩ b kɩɩs Wẽnnaam la A Tʋmtã; la ned ning sẽn kɩɩs Wẽnnaam. (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- La daar ning A sẽn na n bool-b, n yeele: M mako-rãmb bee wãn? (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- Yaa b pa yã Wẽnnaam sẽn naan saasã la tẽngã, t'a tõe n naan wala bãmb? (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- (Sẽn) naan y gũbrã, rẽ poorẽ, yɩɩgã, rẽ poorẽ. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- B na n yeele: Tõnd Soabã! Bõe yĩng tɩ fo pa tʋm tʋmt a yembr n wa tõnd nengẽ, tɩ d tũ f taglã? (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- Rẽ poorẽ, b lebgr yaa b Soabã nengẽ, la a na n vẽneg-b b sẽn da maanã. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- B pa tar bãngr bũmb ningã yĩng ye, b pa tũd, rẽ yĩng ye. (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- Tõnd yã tõnd saamba ne sor a yembr, la tõnd tũud b sora. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- B sẽn kõ Gʋlsʋmã, pa maan waood, rẽ yĩng ye. (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- La Ibrahima sẽn yeele: M Soabã! Maan tɩ tẽng-kãngã yɩɩ laafɩ. (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- A maan y tʋbã, y nifã, la y sũyã; y pa pʋʋs sõma ye. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- B sẽn maan sɛb ne Wẽnnaam taglã, rẽ yĩng ye. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- Bʋd y tũ Ibrahima sorã, sẽn yaa sɩd, la a pa yɩɩ arzɛk-rãmbã sʋka ye. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- La tõnd sẽn fɩk y a Fɩrãuna nebã, b sẽn maan y naong sẽn yaa wẽngã. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- Rẽ yaa sor sẽn yaa tɩrgã, la neb wʋsg pa mi ye. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- Fo pa yã tɩ Wẽnnaam kɩt tɩ bũmb nins sẽn be. (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- Kɩɩsdb na n yeele: Rũndã pa bũmb, rẽ yĩng ye. (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- La b sã n karem tõnd taglã sẽn ka vẽeneg b nengẽ, kɩɩsdb yeela. (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- Arzãan sẽn yaa pʋw-rãmb, dũri sẽn yiid b tẽnga, b na n yɩɩ pʋw-la. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- A maana bũmb ning a sẽn datã; sɩd-sɩda, Wẽnnaam yaa Tõe-la-bũmb-fãa. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- T'a sak y tʋʋm-beedã la a na n dog y, tɩ y wa. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- Yaa b y dat tɩ y kɩɩs tõnd bũmb sẽn yaa tõnd saambã sẽn da tũdã? (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- La fo Soabã sẽn yeele malaaika-rãmbã: Sɩd-sɩda, mam na n naan ned ne zĩm. (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- La a yaa sẽn tʋmd pɛɛmã, sẽn yaa pʋʋs n zĩnd a kʋɩfgã. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- Yeele: Gũ-y tẽngã zug n ges nand tɩɩrã. (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- Sɩd-sɩda, saasã la tẽngã naanegã, la yʋngã la wĩndgã sakrã pʋgẽ. (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- Ãnde n na n dɩk Wẽnnaam sɩd-sõngrã, t'a lebg a n, a wʋs? (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- Bʋd fʋt b taabã ne bũmb sẽn yaa Wẽnnaam sɩdgã, la y pa tũd b sẽn yɩɩdã. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- Yaa b b sẽn gũd, rẽ yĩng ye, malaaika wa bãmb nengẽ, wala fo Soabã wa? (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- Sɩd-sɩda, b sẽn kɩt tɩr-wẽnd ne Wẽnnaamã, pa na n paam ye. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- Wala Fɩrãuna nebã la b sẽn da be b taoorã, b kɩɩs tõnd taglã. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- La a kõ sɩd-rãmb sẽn maan tʋʋma-sõmã, pʋʋs sẽn yaa sẽn pa bõn-tɩrã. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- Wẽnnaam yɩɩda arzɛk ned ning a sẽn datã, a dãmbã sʋka, la a kɩt tɩ ka wʋs. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- La y na n lebg n dɩk bũmb sẽn ka vẽeneg la sẽn vẽenegã, t'a vẽneg y sẽn da maanã. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- La b sẽn zems ne b zĩigã, b sʋka, Wẽnnaam Gʋlsʋmã pʋgẽ. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — yɛlg-mooneg / tõod (tɩ yaa tɩlε, b raag-a, yaa yel-wẽnde)
- mustahabb / mandub (مستحب / مندوب) — b sẽn tagsd tɩ yaa sõnga (sɩd yɩla a maand tɩ yaa kibar, a raag-a, pa yel-wẽnde)
- mubah (مباح) — yaa ne tẽnga / b koos-a (kibar baa a ye, yel-wẽnd baa a ye)
- makruh (مكروه) — b yiis-a (b pa rɩk-a sõng ye, la a maand tɩ pa yel-wẽnde)
- haram (حرام) — b gɩd-a (a maand yaa yel-wẽnde)
- halal (حلال, b koos-a / tõe) — rɩkda mubah ne mustahabb — bũmb ning fãa b sẽn pa gɩd ye
- Yɩl Wẽnnaam yell, la bõos Sorgo/Sõngre. 1:5
- Yɩl Wẽnnaam yell. 2:21
- Ra yɩl Wẽnnaam yell ne yel-kɛng ye. 2:22
- Wẽnnaam la Yãmb n miid (rɩkd taabr), A rɩka Adm (Aleyhis-Salaam) taabr. 2:37
- Ra zẽk sɩda ne zãng ye, la ra sõog sɩda ye. 2:42
- Tũnug yũ-noogo (yu-noog buud fãa), la yik zaka (sɩd-beoogo). 2:43
- Tũnug b ninsaalbã tɩ b maan sõnga, sɩd yɩla yãmb meng sẽn da maan-a. 2:44
- Kos Wẽnnaam sõngre yĩngr fãa pʋgẽ. 2:45
- Ra tũ ninsaal fãa ye, la ra bɩng-y ye. 2:170
- Gũus ne tẽnga, la bɩng-y sẽn da yɩl yãmb fãa. Bɩng-y tũudum sẽn yaa tɩlε, la yãmb sẽn yãk tɩlε. Bɩng-y yel-wẽnd sẽn na n kɩt tɩ Wẽnnaam yolsg yɩ, la b raag a tũudum. Ra bas tɩ yaa-poãn na n kɩt tɩ yãmb maan wẽng ye. 2:177
- Kisaas pʋgẽ (tõod sẽn yaa kẽer ne taab) yãmb tara vɩɩm. 2:179
- Sũum Rammadan kiuugã pʋgẽ. Bɩng-y sũum b sẽn yãk, tɩ yãmb yɩl Wẽnnaam zoeesdb. 2:183
- Yɩl Aalkʋrãan n yaa togs-n-kãsenga. 2:185
- Ra rɩg y taab arzɛka wẽng-yɛng ye, la ra kõ tʋʋmdba m-bɩɩs ye. 2:188
- Ra maan ninsaalb wẽng ye, bɩ yaa goam pʋgẽ bɩ yaa tʋʋm pʋgẽ. Ra kẽng tɔb-biig ye, rɩk tẽnga tɩ yaa gũus. 2:190
- Gũus kɩɩb-biisã. Wala kɩɩb-biisã, tʋm ne b arzɛkã tẽnga, la ra rɩg b arzɛkã ye. 2:220
- Taabr la kos Wẽnnaam yel-wẽn yiisg. Ra maan sɩɩdẽ wã wakatẽ ye. Gũus kâadgã (ninsaal sẽn vɩɩm ne a yam zĩig). 2:222
- Bɩng-y tʋʋm sẽn yaa yãmb zakã pʋgẽ. 2:233
- Yiil zʋʋm-nedba b sẽn tar bɩɩm zugu. 2:247
- Tũudum pʋgẽ pa tɩlε ye. 2:256
- Dɩk-y arzɛka, la maneg-y ne wakat. 2:261
- Ra sãam y sɩd-beoog ne yãmb mengã yɩlgr ye. 2:264
- Pʋʋd ne yãmb tɩ b na n wa paam, la A tagsd yãmb tɩ y maan wẽnsa. 2:268
- Bao ninsaalb sẽn tar tʋlε, la sõng-ba. 2:273
- Ra kẽng n naan rɩba (arza-bũmb) ye. Ra rɩg arza-bũmb sẽn tar rɩba ye. Ra rɩg rɩba ye. 2:275
- Kos sẽn paam-b tɩ b lebg bõe, sɩd yɩla b sẽn be tõndo. 2:280
- Bɩng-y yãmb goamã tʋm-sɛbã pʋgẽ. Yɩl-y tẽnga yãmb arzɛk gomdã pʋgẽ. Tʋm-y tẽnga yãmb sẽn yãk fãa. Sɩd yɩla yãmb sẽn maan arzɛk gomd wakat ningã, bɩng-y tɩ b sɩb. Pʋk-y zʋz-kẽerda, sɩd yɩla yãmb sẽn maan tʋm-sɛb gomd. 2:282
- Gũus ne tẽnga, la bɩng-y yãmb sẽn yɩl yãmb fãa. 2:283
- Kõt-y sɩda ne Gaf-rãmbã, la ne nin-kãnga fãa. 2:285
- Wẽnnaam pa dɩkd nin-kãng tʋm tɩ a pa tõe ye. A paama a sẽn tʋm sõngbã kibar, la a paama a sẽn tʋm wẽngã yel-bẽem. Wẽnnaam pa dɩkd nin-kãng tʋm tɩ a pa tõe ye; tõnd me ra pa tõe d maan woto ye. Bɩng-y Wẽnnaam sẽn tags tɩ a na n maanã, sɩd yɩla tõndo wakat pʋgẽ. 2:286
- Ned fãa sẽn bɩng a sẽn zemsã, la a zoe Wẽnnaam, Wẽnnaam nongda Wẽnnaam zoeesdbã. 3:76
- Maan-y Haaj (tʋm-sɛbã), sɩd yɩla yãmb sẽn tar pãng. 3:97
- Ra kẽng tẽng-n-tẽng ye. 3:103
- Tũnug-y sõnga, la gɩd-y wẽnga. Sõng-y sɩd-manegtã yãmb sasa pʋgẽ. Yiil-y ninsaalbã tɩ b teeg Wẽnnaam. 3:104
- Sɩd-rɩkbã tara tɩlε tɩ b kõt Wẽnnaam bũmb. 3:122
- Ra rɩg rɩba ye. 3:130
- Kɩt-y tɩ yãmb saka Wẽnnaam ne a Tʋmtã, tɩ b yols yãmba. 3:132
- Wẽnnaam nongda ninsaalb sẽn dɩkd (Wẽnnaam sorã pʋgẽ — sɩd-beoog, arzɛk kogre, wala woto) sɩd yɩla b sẽn tar bũmb, la b sẽn tar tʋlɛ wakatẽ, ninsaalb sẽn kiis b sũurã, la ninsaalb sẽn yafa ninsaalbã. 3:134
- Kiis-y sũur. Gɩd-y sũur. 3:134
- Yaf-y, la gãag-y ninsaalb rãmbã yel-wẽndã. 3:135
- Ra yɩl-y goam sẽn pa sõng ye. Maan-y sugre ne ninsaalb sẽn yit yãmb nengẽ. 3:159
- Sɩd yɩla Wẽnnaam sõng yãmba, ned baa a ye pa tõe n zɩɩ yãmba; la A bas yãmba, yãmb pa tara sõngd baa a ye, sɩd yɩla A poorẽ. 3:160
- Nin-kãng fãa na n yɩ kiuudã. La yãmb pa na n paam yãmb kibar fãa, rɩk tɩ yaa Yikri daarã. 3:185
- Tags-y bũmb sẽn yaa kãsenga, wala dũniyã naanegã, la bũmb sẽn be a pʋgẽ. Bãng-y tɩ Wẽnnaam naana dũniyã ne yɛl sẽn tar yĩng, la b sẽn dat. 3:191
- Rɩbã ne paga tar kibar kẽer taab, b sẽn tʋm bũmbã zugu. 3:195
- Ninsaalb sẽn zoe b Soabã, tara Arzãn-naandbã, n pa bubd bũmb tɩ tõe. B na n yɩl n zĩnd b pʋgẽ wakat sẽn kõn sa, wala Wẽnnaam sẽn dat. 3:198
- Maan-y pʋʋd wakat fãa, tɩ yãmb paam Wẽnnaam sũ-noogo. 3:200
- Zoe-y yãmb Soabã, la ra kẽng yel-wẽnd ye. 4:1
- Kõ-y kɩɩb-biisã b arzɛkã, la ra taale yãmb (bũmb sẽn pa sõng) ne b (bũmb sẽn sõng) ye; la ra rɩg b arzɛkã (ne yãmb mengã) ye. 4:2
- Kõ-y pagb (yãmb sẽn na n zɩ) b sɩd-pʋg-bɩɩgã (arzɛk sẽn yaa tɩlε tɩ rɩbã kõ a paga, sɩd yɩla b sẽn maan sɩd-pʋgã wakatẽ) ne sũur sẽn yaa sõnga. 4:4
- Gũus kɩɩb-biisã tɩlε. 4:6
- Kũumã arzɛkã tara tɩlε tɩ b pʋʋs a zakã nebã sʋka. Pagb me tara arzɛk tɩlε. 4:7
- Ra rɩg kɩɩb-biisã arzɛkã wẽng-yɛng ye. 4:10
- Kɩt-y tɩ yãmb saka b sẽn yeel tɩ yaa arzɛk ye. 4:11
- B gɩd tɩ b pa tõe n dɩk pagb arzɛk sɩd yɩla b sẽn datã, la ra maan-b wẽng ye. Zĩnd-y ne b (pagb) sõng-yɛnga. Yɩl-y pagb tɩlε, la gũus-ba. Maan-y yãmb pagã ne yolsg, la ne yel-gũusga. Maan-y pagb ne tɛɛr, la ne tẽnga. 4:19
- Ra zɩ-y ninsaalb sẽn yaa yãmb zʋɩfã ye. 4:23
- Ra kʋ-y yãmb meng ye. Ad Wẽnnaam yaa yolsdb yãmba. Ra rɩg y taab arzɛkã wẽng-yɛng ye. 4:29
- Sɩd yɩla yãmb sẽn zoe yel-wẽnd sẽn yaa kãsengã, Wẽnnaam na n yafa yãmb yel-wẽnd (b sẽn tar tʋlɛ) la A na n kẽes yãmb ne sõng-yɩnga (Arzãna). 4:31
- Ra tags yãmb meng tɩ y yɩ Wẽnnaam sẽn paam ne tẽnga ye. Zoe-y yũ-sõnga, la yũud-wẽnga. 4:32
- Rɩbã la pagb gũusdb, Wẽnnaam sẽn kɩt tɩ b yɩ kẽer n zẽk b taaba, la b sẽn dɩkd b arzɛkã (tɩ b kõ b). Rɩb la zakã gũusd. 4:34
- Yɩl-y Wẽnnaam, la ra zems ne A baa a ye, maan-y sõnga ne yãmb rãmba, la y zʋɩf-rãmbã, la kɩɩb-biisã, la pɛɛmba, la y zak-kãenbã, la y zo-rãmbã, la sor-kẽndba (yãmb sẽn mikd-ba), la yãmb sẽn tar yãmb nug-pɩgẽ wã (yemb-yãmba). Wẽnnaam pa nongd ninsaalb sẽn yaa yãklem-nedba, la sẽn yaa yãklem-tʋmba. Maan-y sõnga ne ninsaal fãa. Yols-y nin-kãsemsã. Gũus-y zakã yel-wẽndã, la yɩl-y y zʋɩf-rãmbã. 4:36
- Ra yɩl yãmb meng tɩ y yaa sũur-kɛlgd ye. 4:37
- Wẽnnaam pa yafd tɩ b zems ne A ye, la A yafda bũmb sẽn yaa a poorẽ wã ne b sẽn dat. 4:48
- Ra yũd ninsaal ye. 4:54
- Wẽnnaam tagsd yãmb tɩ y lebg bũmb sẽn da yɩl yãmb, n kõ a soaba. Sɩd yɩla yãmb sẽn maan tẽnga, yãmb maan-a ne tẽnga. 4:58
- Saka-y Wẽnnaam, la saka-y a Tʋmtã. Yɩl-y ninsaalb sẽn tar pãnga yãmb sʋka. 4:59
- Ra maan ninsaalb sẽn tar tʋlɛ, la sẽn yaa bãas ye. 4:75
- Sõng sẽn wat yãmb nengẽ, yaa Wẽnnaam; la wẽng sẽn wat yãmb nengẽ, yaa yãmb meng n yita. 4:79
- Ned fãa sẽn saka Tʋmtã (Muhammad, salaam be ne a), ad a saka Wẽnnaam. 4:80
- Ned fãa sẽn tʋm sõnga, a paama a kibar; la ned fãa sẽn tʋm wẽnga, a paama a yel-wẽndã. 4:85
- Pa tõe tɩ sɩd-rɩkbã kʋ sɩd-rɩkb, rɩk tɩ yaa tɩlɛ sẽn kẽm. 4:92
- Ned fãa sẽn kʋ sɩd-rɩkb tɩ a mi, a yel-bẽem yaa Jahannam, a na n zĩnd a pʋgẽ. Wẽnnaam sũurã ne a dãmbo be a zugu, la b maan-a ne yel-bẽem sẽn yaa kãsenga. 4:93
- Ned fãa sẽn yi a zakẽ (a tẽngã) Wẽnnaam sorã pʋgẽ, a na n yã dũniyã zugu zĩig bɩɩm, la arzɛk sẽn yaa bʋdo. 4:100
- Bɩng-y yũ-noogã wakatã. 4:103
- Ra sõng ninsaalb sẽn yɩl b tẽnga, la ra yɩl b tʋmt ye. 4:105
- Kos-y Wẽnnaam yel-wẽn yiisg. Wẽnnaam yaa Yaf-ned, Yolsdb. 4:106
- Yãmb nin-kãng sẽn kõt sɩda! Yɩl-y tẽnga, yɩl-y Wẽnnaam kaset rãmba, sɩd yɩla b sẽn yɩl yãmb meng, bɩ yãmb rãmba, bɩ y zʋɩf-rãmbã, sɩd yɩla a sẽn yaa arzɛk soab, bɩ a sẽn yaa pɛɛm soab. Ra bas tɩ tẽnga yãmb paam ye. Maan-y tʋm-tʋmde, tɩ yãmb tʋm tẽnga. 4:135
- Munaafikdbã rat n bãas Wẽnnaam, la A n bãas-ba. 4:142
- Munaafikdbã na n yɩ Bugum pʋgẽ. La yãmb pa na n yã b sõngd baa a ye. 4:145
- Wẽnnaam pa nongd tɩ b gom wẽnga, rɩk tɩ yaa ned sẽn paam wẽnga. 4:148
- Tʋmtã tʋma, tɩ b na n kõ noogo, la b na n zoe-ba, tɩ ninsaalbã pa tõe n yɩ Wẽnnaam yɛl tɩ b paam, sɩd yɩla Tʋmtã. 4:165
- Bɩng-y yãmb sẽn yãkã, la yãmb sẽn yãk tɩlε. 5:1
- Sõng-y taab ne sõnga, la ne Wẽnnaam zoeesgã, la ra sõng-y taab ne yel-wẽndã, la ne wẽnga. 5:2
- Ra rɩg kũumã, la zɩɩmã, la kurugum namã ye. 5:3
- Yɩl-y tẽnga, la ra bas tɩ wẽngã la yãmb tagsdgã kɩt tɩ yãmb maan tẽnga ye. Yɩl-y tẽnga. Bãng-y tɩ tẽngã yaa kẽer ne Wẽnnaam zoeesgã. Ra bas tɩ tẽnga yãmb paam ye. Maan-y tʋm-tʋmde, tɩ yãmb tʋm tẽnga. 5:8
- Bao-y sor sẽn na n kɩt tɩ yãmb kolg Wẽnnaam, la tʋm-y ne pãnga a sorã pʋgẽ. Tɩ yãmb paam. 5:35
- Bɩng-y yãmb sẽn yãk tɩlε, la yãmb sẽn yãkã. 5:89
- Zoe-y bũmb sẽn dɩkd ninsaal, la b sẽn dɩkd tɩ b mi. Zoe-y bũmb sẽn dɩkd ninsaal (bũmb sẽn dɩkd ninsaal fãa), la pʋʋdã, la Al-Ansab (kuy-rãmbã), la Al-Azlam (tɩm sẽn yaa tɩlε, bɩ yel-wẽn), wala woto, ad yaa bũmb sẽn yaa wẽnga, la yaa Pʋʋd tʋmã. 5:90
- Ra kʋ bõn-naandã, sɩd yɩla yãmb sẽn be Ihram pʋgẽ, tɩ y maan Hajj bɩ Umrah (tʋm-sɛbã). 5:95
- Ra sok-y bũmb sẽn pa tar yĩng ye, sɩd yɩla b sẽn na n yɛl yãmba, tʋlε na n paam yãmba. 5:101
- Ra yɩl ninsaalb b soaba bũmb ye. Ra yɩl bũmb sẽn yɩl ninsaalb, tɩ b maan Wẽnnaam wẽnga. 6:108
- Sɩd yɩla yãmb sẽn saka bũmb sẽn yɩl Wẽnnaam, b na n bãas yãmba. B pa tũud bũmb ye, rɩk tɩ yaa tags-goama. 6:116
- (Ninsaal rãmba) Bas-y yel-wẽnd fãa, tɩ yaa sẽn be yɩnga, bɩ sẽn be sõnga. 6:120
- (Sɩd-rɩkbã) Ra rɩg bũmb sẽn pa yɩl Wẽnnaam yʋɩr ye. 6:121
- Ned fãa Wẽnnaam sẽn dat tɩ A kẽes a sorã, A na n pak a sũurã ne Islam; la ned fãa A sẽn dat tɩ A bãas-a, A na n maan a sũurã kɛlgã, la A sẽn yaa tʋlε. 6:125
- Yɩl-y tẽnga yãmb sẽn dɩkd bũmbã pʋgẽ, la ra yɩl bũmb sẽn yaa wẽnga ye. Gũus-y bũmb sẽn yaa nin-kãng fãa. 6:141
- Ra zems ne Wẽnnaam baa a ye; maan-y sõnga ne yãmb rãmba; ra kʋ-y yãmb bi-biisã tɩ yɛsa; ra kẽng yel-wẽndã nengẽ; ra kʋ ned Wẽnnaam sẽn gɩd, rɩk tɩ yaa tẽnga. 6:151
- Yɩl-y tẽnga; ra maan zãnga yãmb tʋm-sɛbã pʋgẽ. Ra kẽng kɩɩb-biig arzɛkã nengẽ, rɩk tɩ yaa tɩlε tɩ b paam-a; kõ-y sɩd-kẽerã, la sɩd-kẽerã, ne tẽnga; sɩd yɩla yãmb sẽn gomd wakat ningã, gom-y sɩda, sɩd yɩla a sẽn yaa y zʋɩf soab, la bɩng-y Wẽnnaam sẽn yãkã. 6:152
- Tũud-y sor sẽn yaa tɩrga, la ra tũud sor (a taabã) ye. B na n kɩt tɩ yãmb yɩ A sorã. 6:153
- (Muhammad) yeele: "Ad m yũ-noogã, m sɩd-beoogã, m vɩɩmã, la m kiuugã, yaa Wẽnnaam, dũniyã Soabã." 6:162
- Ra yɩl-y yãmb meng tɩ yaa kãseng ye. 7:13
- Pʋʋd ra bãas yãmba. 7:27
- (Muhammad) yeele: "M Soabã yeelame tɩ yaa tẽnga…" 7:29
- Bɩng-y Wẽnnaam sẽn gɩd yãmb fãa. Ra kẽng yel-wẽndã pʋgẽ, bɩ yaa goam pʋgẽ, bɩ yaa tʋʋm pʋgẽ. Rɩ-y, la yũ-y, la ra yɩl yãmb meng tɩ yaa wẽng ye. Yɩl-y yãmb sẽn yaa sõnga, sɩd yɩla yũ-noogã wakatẽ. 7:31
- Wẽnnaam naana saasã, la tẽngã, daar a yopoe; la A kẽnga a Kʋdgu zugu (ne a sẽn tar namsgã). 7:54
- Kos-y yãmb Soabã, ne sũur sẽn yaa sõnga, la ne sõnga. A pa nongd ninsaalb sẽn kẽng yel-wẽndã ye. 7:55
- La ra maan wẽng dũniyã zugu, sɩd yɩla b sẽn maan-a tɩ yaa sõnga, la kos-y A ne zoeesg, la ne tẽebga. 7:56
- La ninsaalb sẽn tʋm wẽnga, la b taaba, la b kõta sɩda, ad yãmb Soabã, yaa Yaf-ned, Yolsdb. 7:153
- (Muhammad) yeele: "Ninsaal rãmba! Ad mam yaa Wẽnnaam Tʋmt, ne yãmb fãa…" 7:158
- La yʋy-rãmbã sẽn yaa sõnga fãa, yaa Wẽnnaam. Bɩng-y yãmb tɩ y kos-a ne b, la bas-y ninsaalb sẽn maan yel-wẽnd ne a yʋyã… 7:180
- Ned Wẽnnaam sẽn bãas, a pa tara sor-kɛngd baa a ye; la A bas-ba tɩ b kẽng yel-wẽndã pʋgẽ. 7:186
- Yaf-y, tũnug-y sõnga, la bas-y ninsaalb sẽn pa bãng ye (ra yik-b ye). 7:199
- Yaf-y ninsaalb rãmbã yel-wẽndã. 7:199
- La sɩd yɩla Pʋʋd sẽn kɩt tɩ yãmb tags yel-wẽnda, kos-y Wẽnnaam gũusg. A yaa Wʋmd, Bãngd. 7:200
- Sɩd-rɩkbã, Wẽnnaam sẽn yɩl, b sũurã sũur kiisd, la b sẽn karmd a Aayaaã, b sɩdã paama pãnga. 8:2
- Ra yɩl Wẽnnaam, la a Tʋmtã yel-wẽnd ye; la ra yɩl yãmb sẽn yɩl yãmb (la Wẽnnaam sẽn yeel yãmb fãa) tɩ yãmb mi ye. 8:27
- Sɩd yɩla yãmb sẽn zoe Wẽnnaam, la yãmb saka-a, A na n kõ yãmb tɩ yãmb tõe n zĩnd tẽnga. 8:29
- Sɩd-rɩkbã, b sẽn pa kõt sɩda, b dɩkd b arzɛkã, tɩ b kɩt tɩ ninsaalbã kẽng Wẽnnaam sorã; b na n dɩk-a, la b na n paam. 8:36
- Yeele ninsaalb sẽn pa kõt sɩda: sɩd yɩla b sẽn bas (b sɩd-rɩkdbã), b na n yafa b sẽn maan poorẽ wã. La sɩd yɩla b sẽn lebg n wa, ad bũmb sẽn yit ninsaalb sẽn yɩl bã, b sẽn paam. 8:38
- Sɩd yɩla yãmb sẽn mik ninsaalb sẽn tar pãnga, yɩl-y yãmb meng tɩ yaa kãseng, la tags-y Wẽnnaam yʋɩrã (ne yãmb zĩndbã, la yãmb sũurã), tɩ yãmb paam. 8:45
- Ra yɩl-y ninsaalb sẽn yi b zakẽ, ne yaa-poãn, la b sẽn dat tɩ ninsaalbã yã-b ye. 8:47
- Wẽnnaam pa maan tɛkegr sẽn yit a nengẽ, tɩ b zĩnd a pʋgẽ, rɩk tɩ yaa b sẽn maan tɛkegr b mensẽ. 8:53
- Bõn-naandã sẽn yaa wẽnga, Wẽnnaam nengẽ, yaa ninsaalb sẽn pa kõt sɩda. 8:55
- Wẽnnaam maan bũmb n na n kɩt tɩ sɩd-rɩkbã sũurã yɩ kẽer. 8:63
- Gũus-y, la sõng-y ninsaalb sẽn kos gũusg. 9:6
- Mushrik-rãmbã pa tar tɩlε tɩ b gũus Wẽnnaam masgidã ye. 9:17
- B (sɩd-rɩkbã, Yʋʋd-rãmbã, la Kiris-tãmbã) rat n kiis Wẽnnaam vẽenemgã, (ne b sẽn tʋm Muhammad, salaam be ne a — Tawheed) ne b no-rãmbã, la Wẽnnaam pa dat ye, rɩk tɩ yaa tɩlε tɩ A vẽenemgã paam, sɩd yɩla b sẽn pa nong ye. 9:32
- Sɩd-beoogã (Zaka) yaa: 1) pɛɛmba, 2) ninsaalb sẽn tar tʋlε, 3) ninsaalb sẽn tʋm b zugu, 4) tɩ b paam ninsaalb sẽn dat tɩ b wa ne Islam, 5) tɩ b yiis yemb-yãmba, 6) ninsaalb sẽn tar dĩn-dãmb, 7) Wẽnnaam sorã pʋgẽ (Mujaahid-rãmba), 8) la sor-kẽndba. 9:60
- Ned fãa sẽn kɩd Wẽnnaam, la a Tʋmtã (salaam be ne a), ad a paama Bugum, a na n zĩnd a pʋgẽ. Yaa yel-wẽn sẽn yaa kãsenga. 9:63
- Munaafik-rãmbã, rɩbã la pagbã, b yaa kẽer taab. B yĩmda Wẽnnaam, la A me yĩm-ba. 9:67
- Maan-y pʋʋd tɩ yãmb paam kâadgã. Yɩl-y masgidã tɩ yaa sõnga. 9:108
- Pa tõe tɩ (Nabi, la sɩd-rɩkbã) kos Wẽnnaam yel-wẽn yiisg, tɩ b maan Mushrik-rãmbã, sɩd yɩla b sẽn yaa b zʋɩf-rãmba, sɩd yɩla b sẽn bãng tɩ b na n yɩ Bugum neb ye. 9:113
- Ñoad fãa sẽn maan Wẽnnaam zãnga, bɩ A Aayaa zãnga, n pa tɩrg? Ad yel-wẽnd tʋmdbã pa na n paam ye! 10:17
- B yɩlda Wẽnnaam bũmb sẽn pa tõe n maan-b bũmb, la bũmb sẽn pa tõe n sõng-b, la b yeele: "Ad yaa tõnd ninsaalb sẽn tar tɩlε, ne Wẽnnaam." Yeele: "Yãmb na n tɩ paam Wẽnnaam bũmb sẽn pa be saasẽ, la dũniyã zugu?" Yɩl-y Wẽnnaam yʋɩrã, la A yaa kãseng, ne bũmb sẽn yaa wẽnga. 10:18
- Wẽng tʋmã yel-bẽem yaa wẽng sẽn yaa kẽer. 10:27
- Woto la Wẽnnaam, yãmb Soabã sẽn yaa sɩda. Sɩda poorẽ, bũmb baa a ye sẽn yit b taab? Bɩ yãmb paam. 10:32
- B faa rɩkd tags-goama. Tags-goamã pa sõngd bũmb ye. 10:36
- Ad Wẽnnaam pa maand ninsaal wẽng ye; la ninsaal n maand a meng wẽnga. 10:44
- Bãng-y tɩ Wẽnnaam neerã yaa sõnga, n pa tɩrg bũmb ninsaal sẽn tõe n malg, bɩ a dɩk. 10:58
