- La A naana wɛɛgã, la bũmb sẽn yaa kẽer taab, la bũmb sẽn yaa sõnga, tɩ yãmb kẽng b zugu, la b sẽn yaa sõnga. La A naana bũmb sẽn pa be yãmb bãngrẽ. 16:8
